// ---------- Node-RED Function: Zero Starcount During Daylight ----------
//
// This node runs *after* the MQTT→Influx function.
// If the topic ends in "/starcount" AND flow.get("daytime") is true,
// the numeric value is forced to 0 before writing to InfluxDB.
//
// Expects msg.payload = [fields, tags]
// ------------------------------------------------------------


const isDaytime = global.get("daytime") === true;

if (Array.isArray(msg.payload) && msg.payload.length >= 2) {
    const fields = msg.payload[0];
    const tags = msg.payload[1];
    const topic = tags?.topic || "";

    if (isDaytime && /\/starcount$/i.test(topic)) {
        // Only modify starcount values during daylight
        if ("value_num" in fields) {
            fields.value_num = 0;
        }
    }

    msg.payload[0] = fields;
}

return msg;

// ---------- Node-RED Function: Split camerastatus topics to 2 outputs ----------
//
// Input: from MQTT → InfluxDB v1.x formatter
//   msg.measurement = "live_messages"
//   msg.payload = [
//       { value_num: 1 },
//       { topic: "meteorcams/nz0014/camerastatus" }
//   ]
//
// Output 1 → all normal topics (non-camerastatus)
// Output 2 → camerastatus topics only
//
// ------------------------------------------------------------------------------

let tags = msg.payload?.[1] || {};
let topic = tags.topic || "";

// clone the message so both branches can reuse safely if needed
let normalMsg = RED.util.cloneMessage(msg);
let statusMsg = RED.util.cloneMessage(msg);

// test for camerastatus suffix
if (/\/camerastatus$/i.test(topic)) {
    // route to Output 2 only
    statusMsg.measurement = "camera_status_messages";
    return [null, statusMsg];
} else {
    // route to Output 1 only
    normalMsg.measurement = "live_messages";
    return [normalMsg, null];
}

// ---------- Node-RED Function: Grouped Camera Offline Alert ----------
// Handles multiple cameras going offline close together
// Sends a grouped alert after OFFLINE_DELAY, then reminders every REMIND_INTERVAL
// ---------------------------------------------------------------------

const OFFLINE_DELAY = 10 * 60 * 1000;   // 10 minutes 
const REMIND_INTERVAL = 60 * 60 * 1000; // 60 minutes

const topic = msg.topic || "";
const payload = String(msg.payload).trim();
const match = topic.match(/^meteorcams\/([0-9a-z]+)\/camerastatus$/i);
if (!match) return null;

const id = match[1].toUpperCase();
const now = Date.now();

// node.warn(`Status update for ${id} = ${payload}`);

let statusMap = flow.get("cameraStatus") || {};
statusMap[id] = { value: payload, lastUpdate: now };
flow.set("cameraStatus", statusMap);

// Store timers
let offlineTimer = flow.get("offlineTimer") || null;   // single group timer
let remindTimer  = flow.get("remindTimer")  || null;

// Helper: return all cameras offline > OFFLINE_DELAY
function getOfflineList() {
    const sMap = flow.get("cameraStatus") || {};
    const now = Date.now();
    let offline = [];

    for (const [cam, info] of Object.entries(sMap)) {
        if (info.value === "0" && now - info.lastUpdate > OFFLINE_DELAY) {
            const minsAgo = ((now - info.lastUpdate) / 60000).toFixed(1);
            offline.push({ id: cam, lastSeenMins: parseFloat(minsAgo) });
        }
    }
    return offline;
}

// --- When a camera goes offline ---
if (payload === "0") {
    // start a group alert timer if not already running
    if (!offlineTimer) {
        // node.warn("Starting offline group timer");
        offlineTimer = setTimeout(() => {
            const offline = getOfflineList();
            if (offline.length > 0) {
                // node.warn(`Sending offline alert for ${offline.length} cameras`);
                node.send([
                    { topic: "camera_offline_email",  payload: { label: "10 min", offline } },
                    { topic: "camera_offline_remote", payload: { label: "10 min", offline } }
                ]);
            }

            // Start reminders
            remindTimer = setInterval(() => {
                const offline = getOfflineList();
                if (offline.length > 0) {
                    //node.warn(`Reminder: ${offline.length} cameras still offline`);
                    node.send([
                        { topic: "camera_offline_email",  payload: { label: "60 min", offline } },
                        { topic: "camera_offline_remote", payload: { label: "60 min", offline } }
                    ]);
                }
            }, REMIND_INTERVAL);

            flow.set("remindTimer", remindTimer);
            flow.set("offlineTimer", null);  // reset for next batch
        }, OFFLINE_DELAY);

        flow.set("offlineTimer", offlineTimer);
    }
}

// --- When a camera comes back online ---
else if (payload === "1") {
    // update immediately
    statusMap[id] = { value: "1", lastUpdate: now };
    flow.set("cameraStatus", statusMap);

    // if no more offline cameras, stop timers
    const stillOffline = Object.values(statusMap).some(s => s.value === "0");
    if (!stillOffline) {
        // node.warn("All cameras back online – clearing timers");
        if (offlineTimer) clearTimeout(offlineTimer);
        if (remindTimer) clearInterval(remindTimer);
        flow.set("offlineTimer", null);
        flow.set("remindTimer", null);
    }
}

return null;

// ---------- Node-RED Function C: Remote RED Push Formatter ----------
