// ---------- Node-RED Function A2: MeteorCam Missing / Offline Logic ----------
// Checks if any camera has been silent for >10 minutes
// Sends results to Function B (email) and Function C (remote alert)
// ------------------------------------------------------------------------------

const now = Date.now();
const THRESHOLD = 10 * 60 * 1000;   // ✅ 10 minutes
const REMIND_INTERVAL = 60 * 60 * 1000; // 60 minutes

// stored state
const lastSeen = flow.get("lastSeen") || {};  // last time each camera reported
let lastAlert = flow.get("lastAlert") || {};  // last alert timestamp per camera

let missing = [];  // list of offline devices

for (const [id, t] of Object.entries(lastSeen)) {
    const minsAgo = ((now - t) / 60000).toFixed(1);

    // device has been silent too long
    if (now - t > THRESHOLD) {
        const lastAlertTime = lastAlert[id] || 0;

        // only alert if never alerted or >1hr since last alert
        if (now - lastAlertTime > REMIND_INTERVAL) {
            missing.push({
                id,
                lastSeenMins: parseFloat(minsAgo)
            });
            lastAlert[id] = now;  // record alert time
        }
    } else {
        // device reporting again → clear its alert record
        delete lastAlert[id];
    }
}

// update stored state
flow.set("lastAlert", lastAlert);

// if nothing missing, stop here
if (missing.length === 0) return [null, null];

// structured payload for downstream formatters
const payloadData = {
    label: "Full System off line for + 10mins",
    offline: missing
};

// --- Output 1: for email formatter ---
// --- Output 2: for remote notification formatter ---
const emailMsg = {
    topic: "camera_offline_email",
    payload: payloadData
};

const remoteMsg = {
    topic: "camera_offline_remote",
    payload: payloadData
};

return [emailMsg, remoteMsg];

