return msg;

// ---------- Node-RED Function: Starcount Line Chart (Zero During Daylight) ----------
//
// Expects msg.payload = array of { time, value_num, topic }
// Example topic: meteorcams/nz0014/starcount
//
// Uses flow variable "daytime" (boolean) to force starcount = 0 during daytime.
//
// Output format (for line/scatter chart):
//   msg.payload = [
//       {
//           series: ["NZ0014", "NZ001P", ...],
//           data: [ [ {x:time,y:value}, ... ], [ ... ], ... ],
//           labels: []
//       }
//   ]
// ------------------------------------------------------------------------------

let data = msg.payload || [];

// Read daytime flag (set elsewhere in the flow)
// const isDaytime = flow.get("daytime") === true;

// Extract alphanumeric camera ID (e.g. NZ0014, NZ001P, NZ002K)
function extractCameraID(topic) {
    let match = topic?.match(/nz[0-9a-z]+/i);
    return match ? match[0].toUpperCase() : (topic || "UNKNOWN");
}

// Group by camera/topic
let seriesMap = {};

for (let entry of data) {
    if (!entry || !entry.topic) continue;

    const label = extractCameraID(entry.topic);
    let value = Number(entry.value_num);

    // 🔸 Force starcount to 0 during daylight
    //if (isDaytime && /\/starcount$/i.test(entry.topic)) {
    //    value = 0;
    //}

    if (!seriesMap[label]) seriesMap[label] = [];
    seriesMap[label].push({
        x: new Date(entry.time),
        y: value
    });
}

// Sort each series by time
for (let label in seriesMap) {
    seriesMap[label].sort((a, b) => a.x - b.x);
}

// Build combined chart payload
msg.payload = [{
    series: Object.keys(seriesMap),
    data: Object.values(seriesMap),
    labels: []
}];

// msg.daylight = isDaytime;  // optional for debug or dashboard text node
return msg;

// ---------- Node-RED Function: Influx result → ui-table (show 0s) ----------
//
// Input: msg.payload = [
//   { topic: "meteorcams/nz0014/nextcapstart", value_str: "2025-10-30 07:12:10 UTC" },
//   { topic: "meteorcams/nz0014/meteorcount",  value_num: 3 },
//   { topic: "meteorcams/nz0014/detectioncount", value_num: 0 },
//   ...
// ]
//
// Output: msg.payload = [
//   { Camera: "NZ0014", "Next Capture": "...", "Meteor Count": 3, "Detection Count": 0 },
//   { Camera: "NZ001P", "Next Capture": "", "Meteor Count": 0, "Detection Count": 0 },
//   ...
// ]
// ---------------------------------------------------------------------------

let data = msg.payload || [];

// Helper — extract the NZ camera ID
function extractCameraID(topic) {
    let match = topic?.match(/nz[0-9a-z]+/i);
    return match ? match[0].toUpperCase() : "UNKNOWN";
}

let grouped = {};

// Pass 1 — create entries for every camera we see
for (let row of data) {
    if (!row || !row.topic) continue;
    const cam = extractCameraID(row.topic);
    if (!grouped[cam]) {
        grouped[cam] = {
            Camera: cam,
            "Next Capture": "",
            "Meteor Count": 0,
            "Detection Count": 0
        };
    }
}

// Pass 2 — populate values
for (let row of data) {
    const cam = extractCameraID(row.topic);
    if (!grouped[cam]) continue;

    if (/nextcapstart$/i.test(row.topic)) {
        grouped[cam]["Next Capture"] = row.value_str || "";
    } 
    else if (/meteorcount$/i.test(row.topic)) {
        grouped[cam]["Meteor Count"] = Number(row.value_num) || 0;
    } 
    else if (/detectioncount$/i.test(row.topic)) {
        grouped[cam]["Detection Count"] = Number(row.value_num) || 0;
    }
}

// Convert to array and sort
msg.payload = Object.values(grouped).sort((a, b) => a.Camera.localeCompare(b.Camera));

return msg;

// ---------- Format Influx meteorcount data for bar chart ----------
// Groups by camera ID, one bar per day
// ------------------------------------------------------------------

let data = msg.payload || [];

// Extract camera ID (middle segment like "NZ0014")
function extractCameraID(topic) {
    let match = topic?.match(/\/([a-z]{2}[0-9a-z]+)\//i);
    return match ? match[1].toUpperCase() : "UNKNOWN";
}

// --- Build nested structure: { dateKey: { cameraID: value } } ---
let dailyMap = {};
for (let row of data) {
    const id = extractCameraID(row.topic);
    const dateKey = new Date(row.time).toISOString().slice(0, 10); // YYYY-MM-DD
    if (!dailyMap[dateKey]) dailyMap[dateKey] = {};
    dailyMap[dateKey][id] = Number(row.meteorcount);
}

// --- Get unique camera IDs & dates ---
let cameras = Array.from(
    new Set(Object.values(dailyMap).flatMap(obj => Object.keys(obj)))
).sort();
let dates = Object.keys(dailyMap).sort();

// --- Build bar chart structure ---
let chartData = cameras.map(id =>
    dates.map(date => dailyMap[date][id] || 0)
);

// --- Output payload for Node-RED Dashboard bar chart ---
msg.payload = [{
    series: cameras,   // one series per camera
    data: chartData,   // counts per day
    labels: dates      // X-axis labels (dates)
}];

return msg;

